/// <summary>击鼓 Drumming: On every beat a flash hits the centre and a ring expands outward and fades.</summary>
public sealed class DrummingEffect : EffectGenerator, ILoopable
{
    public const string EffectId = "Drumming";

    public DrummingEffect()
